:root {
  --ink: #243047;
  --paper: #fffdf7;
  --violet: #7058c7;
  --pink: #f5c4da;
  --line: #ded8ec;
}

.ticket {
  width: 440px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 16px;
}

.ticket-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 16px;
  color: var(--paper);
  background: var(--violet);
}

.rink-name {
  font-size: 14px;
  font-weight: 700;
}

.status {
  padding: 3px 7px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.8px;
  color: var(--violet);
  background: var(--pink);
  border-radius: 999px;
}

.ticket-body {
  display: flex;
  align-items: center;
  gap: 15px;
  padding: 16px;
}

.date-block {
  display: flex;
  align-items: center;
  gap: 7px;
  padding-right: 15px;
  border-right: 1px dashed var(--line);
}

.date-block strong {
  font-size: 38px;
  line-height: 1;
  color: var(--violet);
}

.date-block span,
.eyebrow {
  font-size: 10px;
  font-weight: 800;
  line-height: 1.25;
  letter-spacing: 0.8px;
}

.eyebrow {
  margin: 0 0 3px;
  color: var(--violet);
}

.rental-details h1 {
  margin: 0;
  font-size: 20px;
  line-height: 1.15;
}

.rental-details p:last-child {
  margin: 5px 0 0;
  font-size: 13px;
}

.ticket-footer {
  display: flex;
  justify-content: space-between;
  padding: 9px 16px;
  font-size: 11px;
  color: var(--ink);
  background: var(--pink);
}
